CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_384( p_query vector(384), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_384 <=> p_query)::float8, encode(c.chash, 'hex') FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) ORDER BY c.embedding_384 <=> p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_768( p_query vector(768), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_768 <=> p_query)::float8, encode(c.chash, 'hex') FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) ORDER BY c.embedding_768 <=> p_query LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.search_metadata_scoped_1024( p_query vector(1024), p_collections text[], p_content_type text, p_author text, p_year int, p_corpus text, p_subtree text, p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, chash text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT d.tumbler, c.chunk_text, c.collection, (c.embedding_1024 <=> p_query)::float8, encode(c.chash, 'hex') FROM nexus.chunks c JOIN nexus.catalog_document_chunks m ON m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_content_type IS NULL OR d.content_type = p_content_type) AND (p_author IS NULL OR d.author ILIKE '%' || p_author || '%') AND (p_year IS NULL OR d.year = p_year) AND (p_corpus IS NULL OR d.corpus = p_corpus) AND d.alias_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) ORDER BY c.embedding_1024 <=> p_query LIMIT p_n $$;

