CREATE OR REPLACE FUNCTION nexus.chash_conformance_report(dim int) RETURNS TABLE( table_name text, total bigint, non_conformant bigint, sample_chashes text[] ) LANGUAGE plpgsql SECURITY INVOKER AS $$ BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'chash_conformance_report: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
IF dim = 384 THEN RETURN QUERY SELECT 'nexus.chunks_384'::text, (SELECT count(*) FROM nexus.chunks WHERE embedding_384 IS NOT NULL)::bigint, (SELECT count(*) FROM nexus.chunks WHERE embedding_384 IS NOT NULL AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.chunks WHERE embedding_384 IS NOT NULL AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); RETURN QUERY SELECT 'nexus.catalog_document_chunks'::text, (SELECT count(*) FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('minilm-l6-v2-384'))::bigint, (SELECT count(*) FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('minilm-l6-v2-384') AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('minilm-l6-v2-384') AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]);
ELSIF dim = 768 THEN RETURN QUERY SELECT 'nexus.chunks_768'::text, (SELECT count(*) FROM nexus.chunks WHERE embedding_768 IS NOT NULL)::bigint, (SELECT count(*) FROM nexus.chunks WHERE embedding_768 IS NOT NULL AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.chunks WHERE embedding_768 IS NOT NULL AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); RETURN QUERY SELECT 'nexus.catalog_document_chunks'::text, (SELECT count(*) FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('bge-base-en-v15-768'))::bigint, (SELECT count(*) FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('bge-base-en-v15-768') AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('bge-base-en-v15-768') AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]);
ELSIF dim = 1024 THEN RETURN QUERY SELECT 'nexus.chunks_1024'::text, (SELECT count(*) FROM nexus.chunks WHERE embedding_1024 IS NOT NULL)::bigint, (SELECT count(*) FROM nexus.chunks WHERE embedding_1024 IS NOT NULL AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.chunks WHERE embedding_1024 IS NOT NULL AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); RETURN QUERY SELECT 'nexus.catalog_document_chunks'::text, (SELECT count(*) FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('voyage-code-3', 'voyage-context-3', 'voyage-3'))::bigint, (SELECT count(*) FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('voyage-code-3', 'voyage-context-3', 'voyage-3') AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('voyage-code-3', 'voyage-context-3', 'voyage-3') AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); END IF; END; $$

