ELSIF dim = 1024 THEN RETURN QUERY SELECT 'nexus.chunks_1024'::text, (SELECT count(*) FROM nexus.chunks_1024)::bigint, (SELECT count(*) FROM nexus.chunks_1024 WHERE octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.chunks_1024 WHERE octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); RETURN QUERY SELECT 'nexus.catalog_document_chunks'::text, (SELECT count(*) FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('voyage-code-3', 'voyage-context-3', 'voyage-3'))::bigint, (SELECT count(*) FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('voyage-code-3', 'voyage-context-3', 'voyage-3') AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.catalog_document_chunks WHERE collection IS NOT NULL AND split_part(collection, '__', 3) IN ('voyage-code-3', 'voyage-context-3', 'voyage-3') AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); END IF; END; $$

