           AND collection = p_quarantine_collection
           AND COALESCE(metadata->>'origin_collection', p_origin_collection) = p_origin_collection;

        v_expired := COALESCE(array_length(v_chashes, 1), 0);
        v_refused := COALESCE(array_length(v_protected, 1), 0);

        IF v_expired = 0 THEN
            RETURN QUERY SELECT 0::bigint, v_refused;
