CREATE OR REPLACE FUNCTION nexus.purge_trash(older_than interval) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_tenant TEXT; v_count BIGINT; BEGIN -- GUC guard: must have a non-empty tenant scope v_tenant := current_setting('nexus.tenant', true); IF v_tenant IS NULL OR v_tenant = '' THEN RAISE EXCEPTION 'purge_trash: nexus.tenant GUC must be set to a non-empty tenant scope. ' 'Cross-tenant purge is not permitted. Set the nexus.tenant configuration ' 'parameter before calling purge_trash.'; END IF;
-- Step 1-3 (collapsed): sweep orphaned chunk rows from the unified -- nexus.chunks. Safety contract unchanged from catalog-026-1: a chunk -- is sweepable ONLY IF it has at least one manifest row AND none of its -- manifest rows PROTECT it -- a row protects when its owning document -- is LIVE, or TOMBSTONED but still inside the older_than grace window. -- Manifest-less chunks are never swept (RDR-145 deferred scope). DELETE FROM nexus.chunks c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than) );
-- Step 4: physically delete tombstoned documents older than the threshold. -- fk-001 ON DELETE CASCADE removes catalog_document_chunks, document_aspects, -- document_highlights, and aspect_extraction_queue rows for each deleted doc. -- Unchanged from catalog-026-1. DELETE FROM nexus.catalog_documents WHERE tenant_id = v_tenant AND deleted_at IS NOT NULL AND deleted_at <= NOW() - older_than;
GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count; END; $$

